import fs from 'node:fs';
import path from 'node:path';
import os from 'node:os';
import crypto from 'node:crypto';
import { spawn } from 'node:child_process';
import { scheduleReplace } from '../../packages/cli/src/lib/packer/pack-update-applier.js';

const dir = fs.mkdtempSync(path.join(fs.realpathSync.native(os.tmpdir()), 'cc-updater-eventloop-'));
const target = path.join(dir, 'current.exe');
const staged = `${target}.new`;
fs.writeFileSync(target, 'old-bytes');
fs.writeFileSync(staged, 'new-bytes');
const expectedSha256 = crypto.createHash('sha256').update('new-bytes').digest('hex');
const source = new URL('../../packages/cli/src/lib/packer/pack-update-applier.js', import.meta.url);
const events = [];
const start = performance.now();
const mark = (event, fields = {}) => {
  const row = { event, elapsedMs: Number((performance.now() - start).toFixed(1)), ...fields };
  events.push(row);
  process.stdout.write(`${JSON.stringify(row)}\n`);
};
let nativeErrorDelivered = false;
mark('start', { sourceSha256: crypto.createHash('sha256').update(fs.readFileSync(source)).digest('hex'), fixture: dir });
try {
  await scheduleReplace({
    newExePath: staged,
    targetExePath: target,
    expectedSha256,
    platform: 'win32',
    verify: false,
    spawnImpl() {
      const child = spawn(path.join(dir, 'nonexistent-sidecar.exe'), [], { stdio: 'ignore', windowsHide: true });
      mark('native-spawn-returned', { pid: child.pid ?? null });
      child.once('error', error => {
        nativeErrorDelivered = true;
        mark('native-error', { code: error.code });
      });
      child.once('close', (code, signal) => mark('native-close', { code, signal }));
      return child;
    },
  });
  mark('unexpected-success');
} catch (error) {
  mark('schedule-rejected', { code: error.code, nativeErrorDelivered, lockExists: fs.existsSync(`${target}.update.lock`) });
}
await new Promise(resolve => setImmediate(resolve));
await new Promise(resolve => setImmediate(resolve));
const report = {
  sourceCommit: '13095fd42635a580f4d88eaada5ef01ec0553ce1',
  productionChanges: false,
  deadlinesChanged: false,
  events,
  targetUnchanged: fs.readFileSync(target, 'utf8') === 'old-bytes',
  stagedUnchanged: fs.readFileSync(staged, 'utf8') === 'new-bytes',
  lockExists: fs.existsSync(`${target}.update.lock`),
};
fs.writeFileSync(new URL('./updater-eventloop-probe-13095.json', import.meta.url), JSON.stringify(report, null, 2));

import fs from 'node:fs';
import path from 'node:path';
import os from 'node:os';
import crypto from 'node:crypto';
import { spawn } from 'node:child_process';
import { scheduleReplace } from '../../packages/cli/src/lib/packer/pack-update-applier.js';

const dir = fs.mkdtempSync(path.join(fs.realpathSync.native(os.tmpdir()), 'cc-updater-eventloop-'));
const target = path.join(dir, 'current.exe');
const staged = `${target}.new`;
fs.writeFileSync(target, 'old-bytes');
fs.writeFileSync(staged, 'new-bytes');
const expectedSha256 = crypto.createHash('sha256').update('new-bytes').digest('hex');
const source = new URL('../../packages/cli/src/lib/packer/pack-update-applier.js', import.meta.url);
const events = [];
const mode = process.argv[2] || 'spawn-error';
const exitWitness = path.join(dir, 'child-exit-witness.json');
const wallStart = Date.now();
const start = performance.now();
const mark = (event, fields = {}) => {
  const row = { event, elapsedMs: Number((performance.now() - start).toFixed(1)), ...fields };
  events.push(row);
  process.stdout.write(`${JSON.stringify(row)}\n`);
};
let nativeErrorDelivered = false;
let nativeExitDelivered = false;
let spawnedChild;
mark('start', { sourceSha256: crypto.createHash('sha256').update(fs.readFileSync(source)).digest('hex'), fixture: dir });
try {
  await scheduleReplace({
    newExePath: staged,
    targetExePath: target,
    expectedSha256,
    platform: 'win32',
    verify: false,
    spawnImpl() {
      const child = mode === 'early-exit'
        ? spawn(process.execPath, ['-e', `require('node:fs').writeFileSync(${JSON.stringify(exitWitness)}, JSON.stringify({at:Date.now(),pid:process.pid}));process.exit(7);`], { stdio: 'ignore', windowsHide: true })
        : spawn(path.join(dir, 'nonexistent-sidecar.exe'), [], { stdio: 'ignore', windowsHide: true });
      spawnedChild = child;
      mark('native-spawn-returned', { pid: child.pid ?? null });
      child.once('error', error => {
        nativeErrorDelivered = true;
        mark('native-error', { code: error.code });
      });
      child.once('exit', (code, signal) => {
        nativeExitDelivered = true;
        mark('native-exit', { code, signal });
      });
      child.once('close', (code, signal) => mark('native-close', { code, signal }));
      return child;
    },
  });
  mark('unexpected-success');
} catch (error) {
  let childAlive = null;
  if (spawnedChild?.pid) {
    try { process.kill(spawnedChild.pid, 0); childAlive = true; } catch (error) { childAlive = error.code !== 'ESRCH'; }
  }
  const witness = fs.existsSync(exitWitness) ? JSON.parse(fs.readFileSync(exitWitness, 'utf8')) : null;
  mark('schedule-rejected', { code: error.code, nativeErrorDelivered, nativeExitDelivered, childAlive, childExitIntentMs: witness ? witness.at - wallStart : null, lockExists: fs.existsSync(`${target}.update.lock`) });
}
await new Promise(resolve => setImmediate(resolve));
await new Promise(resolve => setImmediate(resolve));
const report = {
  sourceCommit: '13095fd42635a580f4d88eaada5ef01ec0553ce1',
  mode,
  productionChanges: false,
  deadlinesChanged: false,
  events,
  targetUnchanged: fs.readFileSync(target, 'utf8') === 'old-bytes',
  stagedUnchanged: fs.readFileSync(staged, 'utf8') === 'new-bytes',
  lockExists: fs.existsSync(`${target}.update.lock`),
};
fs.writeFileSync(new URL(`./updater-eventloop-probe-13095${mode === 'early-exit' ? '-early-exit' : ''}.json`, import.meta.url), JSON.stringify(report, null, 2));

import fs from 'node:fs';
import path from 'node:path';
import os from 'node:os';
import crypto from 'node:crypto';
import { spawn, execFileSync } from 'node:child_process';
import { fileURLToPath, pathToFileURL } from 'node:url';

const [requestedRoot, mode, outputFile] = process.argv.slice(2);
if (!requestedRoot || !['spawn-error', 'early-exit'].includes(mode) || !outputFile) throw new Error('Usage: probe.mjs repository-root spawn-error|early-exit output.json');
const root = fs.realpathSync.native(path.resolve(requestedRoot));
const sourcePath = path.join(root, 'packages/cli/src/lib/packer/pack-update-applier.js');
const digest = value => crypto.createHash('sha256').update(value).digest('hex');
const git = (...args) => execFileSync('git', ['-C', root, ...args], { encoding: 'utf8', windowsHide: true }).trim();
const sourceSha256Before = digest(fs.readFileSync(sourcePath));
const sourceCommitBefore = git('rev-parse', 'HEAD');
const trackedStatusBefore = git('status', '--short', '--untracked-files=no');
const { scheduleReplace, WINDOWS_SIDECAR_READY_TIMEOUT_MS } = await import(pathToFileURL(sourcePath));
if (WINDOWS_SIDECAR_READY_TIMEOUT_MS !== 30_000) throw new Error('Production readiness deadline changed');

const dir = fs.mkdtempSync(path.join(fs.realpathSync.native(os.tmpdir()), 'cc-updater-eventloop-'));
const target = path.join(dir, 'current.exe');
const staged = `${target}.new`;
const exitWitness = path.join(dir, 'child-exit-witness.json');
fs.writeFileSync(target, 'old-bytes');
fs.writeFileSync(staged, 'new-bytes');
const expectedSha256 = digest('new-bytes');
const events = [];
const wallStart = Date.now();
const start = performance.now();
const mark = (event, fields = {}) => {
  const row = { event, elapsedMs: Number((performance.now() - start).toFixed(1)), ...fields };
  events.push(row);
  process.stdout.write(`${JSON.stringify(row)}\n`);
};
let nativeErrorDelivered = false;
let nativeExitDelivered = false;
let spawnedChild;
mark('start', { sourceSha256: sourceSha256Before });
try {
  await scheduleReplace({
    newExePath: staged,
    targetExePath: target,
    expectedSha256,
    platform: 'win32',
    verify: false,
    spawnImpl() {
      const child = mode === 'early-exit'
        ? spawn(process.execPath, ['-e', `require('node:fs').writeFileSync(${JSON.stringify(exitWitness)}, JSON.stringify({at:Date.now(),pid:process.pid}));process.exit(7);`], { stdio: 'ignore', windowsHide: true })
        : spawn(path.join(dir, 'nonexistent-sidecar.exe'), [], { stdio: 'ignore', windowsHide: true });
      spawnedChild = child;
      mark('native-spawn-returned', { pid: child.pid ?? null });
      child.once('error', error => { nativeErrorDelivered = true; mark('native-error', { code: error.code }); });
      child.once('exit', (code, signal) => { nativeExitDelivered = true; mark('native-exit', { code, signal }); });
      child.once('close', (code, signal) => mark('native-close', { code, signal }));
      return child;
    },
  });
  mark('unexpected-success');
} catch (error) {
  let childAlive = null;
  if (spawnedChild?.pid) {
    try { process.kill(spawnedChild.pid, 0); childAlive = true; } catch (error) { childAlive = error.code !== 'ESRCH'; }
  }
  const witness = fs.existsSync(exitWitness) ? JSON.parse(fs.readFileSync(exitWitness, 'utf8')) : null;
  mark('schedule-rejected', { code: error.code, nativeErrorDelivered, nativeExitDelivered, childAlive, childExitIntentMs: witness ? witness.at - wallStart : null, lockExists: fs.existsSync(`${target}.update.lock`) });
}
await new Promise(resolve => setImmediate(resolve));
await new Promise(resolve => setImmediate(resolve));
const sourceSha256After = digest(fs.readFileSync(sourcePath));
const sourceCommitAfter = git('rev-parse', 'HEAD');
const trackedStatusAfter = git('status', '--short', '--untracked-files=no');
const report = {
  schema: 'chainlesschain.updater-eventloop-probe/v1',
  mode,
  host: { node: process.version, platform: process.platform, arch: process.arch },
  sourceCommitBefore, sourceCommitAfter, sourceSha256Before, sourceSha256After,
  trackedStatusBefore, trackedStatusAfter,
  probeSha256: digest(fs.readFileSync(fileURLToPath(import.meta.url))),
  readinessTimeoutMs: WINDOWS_SIDECAR_READY_TIMEOUT_MS,
  fixture: dir,
  events,
  targetUnchanged: fs.readFileSync(target, 'utf8') === 'old-bytes',
  stagedUnchanged: fs.readFileSync(staged, 'utf8') === 'new-bytes',
  lockExists: fs.existsSync(`${target}.update.lock`),
};
fs.writeFileSync(path.resolve(outputFile), `${JSON.stringify(report, null, 2)}\n`);
if (sourceSha256Before !== sourceSha256After || sourceCommitBefore !== sourceCommitAfter) throw new Error('Source changed while probing');
const rejected = events.find(event => event.event === 'schedule-rejected');
const terminal = events.find(event => event.event === (mode === 'spawn-error' ? 'native-error' : 'native-exit'));
if (!rejected || rejected.code !== 'SIDECAR_NOT_READY' || !terminal || terminal.elapsedMs >= rejected.elapsedMs || rejected.elapsedMs >= 5_000 || !report.targetUnchanged || !report.stagedUnchanged || !report.lockExists) throw new Error('Asynchronous readiness regression probe failed');
